Definition exB_sub_ok (C : lctx) (A Ar : AS) (E : env) (b : expr * Z * Z * Z * Z * Z) : Prop :=
  match b with (rb, lo, hi, q, p, n) =>
    edenot E rb = Z_to_bv 64 q /\ 0 <= q < 2 ^ 64 /\ 0 <= p < 2 ^ 64 /\
    live A (Z_to_bv 64 p) = Some n /\ live Ar (Z_to_bv 64 p) = None /\ live (c_A0 C) (Z_to_bv 64 p) = None /\
    p <= q + lo /\ q + hi <= p + n end.
Definition exB_sub_region (b : expr * Z * Z * Z * Z * Z) : expr * Z * Z := match b with (rb, lo, hi, _, _, _) => (rb, lo, hi) end.

Lemma exB_win_subs : forall C A Ar m md E log (rb : expr) (s F : Z) (subs : list (expr * Z * Z * Z * Z * Z)),
  Cok C -> W C A m md -> sub_live Ar A -> log_flat E log ->
  ex_in_regions ((rb, (- F)%Z, 0%Z) :: map exB_sub_region subs) log = true -> edenot E rb = Z_to_bv 64 s ->
  0 <= F -> c_top C - LSTK <= s - F -> s <= c_top C -> Forall (exB_sub_ok C A Ar E) subs ->
  W C A (mem_denot E m log) md /\ POSTM C Ar s m (mem_denot E m log).
