Definition exB_reg_in (E : env) (R : list (Z * Z)) (r : expr * Z * Z) : Prop :=
  match r with (rb, lo, hi) => exists z n, In (z, n) R /\ z <= u (edenot E rb) + lo /\ u (edenot E rb) + hi <= z + n end.

Lemma exB_rinv : forall E m log (regions : list (expr * Z * Z)) (R : list (Z * Z)),
  log_flat E log -> ex_in_regions regions log = true -> Forall (exB_reg_in E R) regions -> rinv R m (mem_denot E m log).
