Definition exB_log_regions (log : list sentry) : list (expr * Z * Z) :=
  map (fun e => match e with SE (SA b off) w _ => (b, off, (off + Z.of_nat w)%Z) end) log.
Ltac exB_run fuel stops scr HR HK R' HR' Hlf Hms :=
  lazymatch type of HR with
  | regs_ok ?E ?sr ?regs =>
    lazymatch type of HK with
    | know_ok ?segs _ ?base ?kn =>
      lazymatch goal with
      | |- context [mkst regs (Z_to_bv 64 ?pc) base ?rom] =>
          let nx := ex_nx E in
          let r := eval vm_compute in (sym_exec segs fuel true stops scr (SS pc sr [] kn nx) []) in
          lazymatch r with
          | (?ss', ?scs, ?scr') =>
              let Hsc := fresh "Hsc" in let Hex := fresh "Hex" in
              assert (Hex : sym_exec segs fuel true stops scr (SS pc sr [] kn nx) [] = (ss', scs, scr')) by (vm_cast_no_check (eq_refl (ss', scs, scr')));
              assert (Hsc : scs_denot segs base E scs);
              [ split_scs; ex_sc regs
              | destruct (run_sound segs fuel stops scr pc sr kn nx ss' scs scr' E base rom regs
                          Hex HR HK Hsc) as (R' & HR' & Hlf & Hms);
                clear Hsc Hex ]
          end
      end
    end
  end.

Ltac exB_rinv_tac Hlf R :=
  lazymatch type of Hlf with
  | log_flat ?E ?log =>
      let regions := eval vm_compute in (exB_log_regions log) in
      apply (exB_rinv E _ log regions R Hlf ltac:(vm_cast_no_check (eq_refl true)))
  end.

(* [comment removed for export] *)
Ltac exB_reg_tac tacE :=
  repeat (apply Forall_cons || apply Forall_nil);
  (unfold exB_reg_in; ex_unfoldE; cbn [edenot ev ex_envL vals_ev map app ex_regs_list nth Nat.add]; tacE; rewrite ?u_Z2bv by lia;
   first [ (eexists _, _; split; [left; reflexivity | lia])
         | (eexists _, _; split; [right; left; reflexivity | lia])
         | (eexists _, _; split; [right; right; left; reflexivity | lia])
         | (eexists _, _; split; [right; right; right; left; reflexivity | lia]) ]).

(* [comment removed for export] *)
Ltac exB_cell HK Hlf rb rk n a z name tacS tacA tacV :=
  lazymatch type of HK with
  | know_ok ?segs ?E ?m ?kn =>
    lazymatch type of Hlf with
    | log_flat _ ?log =>
      let lk := eval vm_compute in (ex_lookup segs kn log rb rk n) in
      lazymatch lk with
      | Some (?v, ?scs) =>
          let scs0 := eval vm_compute in (flat_sc kn (SA rb rk) n ++ scs) in
          assert (name : rdn segs (mem_denot E m log) (Z_to_bv 64 a) n = Some (Z_to_le_bytes n z));
          [ apply (ex_cell_Z segs E m kn log rb rk n v scs scs0 a z HK Hlf ltac:(lia) ltac:(lia) ltac:(vm_cast_no_check (eq_refl lk)) ltac:(vm_cast_no_check (eq_refl scs0)));
            [ tacS | tacA | tacV | cbn [Z.of_nat Pos.of_succ_nat Pos.succ Z.mul Pos.mul]; lia ] | ]
      | _ => fail 100 "exB_cell: no value at" rb rk
      end
    end
  end.

(* [comment removed for export] *)
Ltac exB_tacA tacE :=
  unfold adenot; cbn [a_base a_off]; ex_unfoldE; cbn [edenot ev ex_envL vals_ev map app ex_regs_list nth Nat.add]; tacE;
  rewrite ?zbv_addi; first [ reflexivity | (f_equal; lia) ].
Ltac exB_tacV tacE :=
  ex_unfoldE; cbn [edenot ev ex_envL vals_ev map app ex_regs_list nth Nat.add]; tacE;
  repeat first [ rewrite ext_val_sx_id by (first [ lia | (rewrite ?u_Z2bv by lia; ex_pow2; lia) ])
               | rewrite ext_val_zx_id by (rewrite ?u_Z2bv by lia; ex_pow2; lia)
               | rewrite alu_add | rewrite alu_sub | rewrite zbv_add | rewrite zbv_sub | rewrite m_mul | rewrite zbv_mul
               | rewrite w_addw | rewrite zbv_addw_small by lia ];
  first [ reflexivity | (f_equal; lia) ].

(* [comment removed for export] *)
(* [comment removed for export] *)
Ltac exB_sc_hook :=
  repeat rewrite ext_val_sx_id by (first [ lia | (rewrite ?u_Z2bv by lia; ex_pow2; lia) ]);
  rewrite ?w_addw; rewrite ?zbv_addw_small by lia; ex_br.   (* [comment removed for export] *)
Ltac ex_sc regs ::=
  ex_unfoldE; unfold sc_denot, flat, estart, elenZ, adenot;
  cbn [a_base a_off edenot ev ex_envL vals_ev map app ex_regs_list nth Nat.add];
  repeat match goal with H : getr regs _ = Z_to_bv 64 _ |- _ => rewrite H end;
  rewrite ?ex_ptr_val, ?zbv_addi;
  first [ lia | (rewrite ?u_Z2bv by lia; lia) | ex_br | exB_sc_hook | idtac ].

