Section DropCell.
Context {fx : FPState}.
#[local] Notation "'u'" := bv_unsigned (only parsing).
Lemma rinv_drop_cell : forall segs (R : list (Z * Z)) (m M' : word -> option byte) (a : Z) (n : nat) (bs : list byte),
  rinv (R ++ [(a, Z.of_nat n)]) m M' -> 0 <= a -> a + Z.of_nat n <= 2 ^ 64 -> length bs = n ->
  (forall i, 0 <= i < Z.of_nat n -> m (Z_to_bv 64 (a + i)) <> None) ->
  rdn segs m (Z_to_bv 64 a) n = Some bs -> rdn segs M' (Z_to_bv 64 a) n = Some bs -> rinv R m M'.
