Ltac exB_closed_hyp E L fr r G cont :=
  match goal with
  | H : reg_get fr ?r' = Z_to_bv 64 ?z |- _ =>
      let a := eval vm_compute in (Nat.eqb (ridx r') (ridx r)) in
      lazymatch a with
      | true => assert (G : reg_get (fr_denot E L fr) r = Z_to_bv 64 z)
                  by (apply (fr_get_hyp E L fr r r' z); [vm_cast_no_check (eq_refl (@None expr)) | vm_cast_no_check (eq_refl (ridx r)) | exact H]);
                cont z
      end
  end.
Ltac exf_closed E L fr r G cont ::=
  let o := eval vm_compute in (fr_find L (ridx r)) in
  lazymatch o with
  | Some (ELit ?z) =>
      assert (G : reg_get (fr_denot E L fr) r = Z_to_bv 64 z) by (apply fr_get_lit; vm_cast_no_check (eq_refl (Some (ELit z))));
      cont z
  | None => first [ exB_closed_hyp E L fr r G cont | fail 100 "exf: FP register" r "holds no closed value (no list entry, no hypothesis)" ]
  | _ => fail 100 "exf: FP register" r "does not hold a closed value:" o
  end.

