Ltac exB_fr_expr :=
  lazymatch goal with
  | |- reg_get (fr_denot ?E ?L ?fr) ?r = _ =>
      let o := eval vm_compute in (fr_find L (ridx r)) in
      lazymatch o with
      | Some ?e => rewrite (fr_get_expr E L fr r e ltac:(vm_cast_no_check (eq_refl o)))
      | _ => fail 100 "exB_fr_expr: register" r "was not written by the session"
      end
  end.

